from django.db.models import OuterRef, Subquery

_SEVERITY_RANK = {"critical": 0, "high": 1, "medium": 2, "low": 3, "info": 4}


def backfill_v2(apps, schema_editor):
    """Carry v1 rows over to the v2 vocabulary without dropping them.

    v1 runs keep an empty plan_hash, which excludes them from canonical
    measurement selection (v1 results were fail-open: a crashed tool was
    stored as 0 findings), but they stay inspectable.
    """
    Finding = apps.get_model("analysis", "Finding")
    ToolResult = apps.get_model("analysis", "ToolResult")
    AnalysisRun = apps.get_model("analysis", "AnalysisRun")
    results = ToolResult.objects.filter(pk=OuterRef("result_id"))
    Finding.objects.filter(run__isnull=True).update(
        run_id=Subquery(results.values("run_id")[:1]),
        tool_slug=Subquery(results.values("tool_slug")[:1]),
    )
    for severity, rank in _SEVERITY_RANK.items():
        Finding.objects.filter(severity=severity).update(severity_rank=rank)
    ToolResult.objects.filter(status="completed").update(status="succeeded")
    AnalysisRun.objects.filter(status="pending").update(status="queued")
    AnalysisRun.objects.filter(status="running").update(
        status="failed",
        error_message="Interrupted v1 run (superseded by analysis engine v2)",
    )


